/// Cyclic progress indicator with a braille spinner frame.
///
/// `next()` advances the spinner and increments the current count.
/// `str()` renders the current frame followed by the completion
/// percentage with one decimal place, e.g. `⢿ 60.0%`.
pub struct CyclicProgress {
    total: u64,
    current: u64,
}

/// Classic 8-frame braille spinner cycle.
const FRAMES: [char; 8] = ['⣾', '⣽', '⣻', '⢿', '⡿', '⣟', '⣯', '⣷'];

impl CyclicProgress {
    pub fn new(total: u64) -> Self {
        CyclicProgress { total, current: 0 }
    }

    pub fn next(&mut self) {
        self.current += 1;
    }

    pub fn percentage(&self) -> f64 {
        self.current as f64 / self.total as f64 * 100.0
    }

    pub fn str(&self) -> String {
        let frame = FRAMES[(self.current % FRAMES.len() as u64) as usize];
        format!("{} {:.1}%", frame, self.percentage())
    }
}

