/// Progress display tracking a current value against a total.
///
/// `display()` renders e.g. `Progress: 50.0% (25/50)`.
pub struct ProgressDisplay {
    total: u64,
    current: u64,
}

impl ProgressDisplay {
    pub fn new(total: u64) -> Self {
        ProgressDisplay { total, current: 0 }
    }

    pub fn update(&mut self, value: u64) {
        self.current = value;
    }

    pub fn increment(&mut self, amount: u64) {
        self.current += amount;
    }

    pub fn percentage(&self) -> f64 {
        self.current as f64 / self.total as f64 * 100.0
    }

    pub fn display(&self) -> String {
        format!(
            "Progress: {:.1}% ({}/{})",
            self.percentage(),
            self.current,
            self.total
        )
    }
}

