/// Static formatting helpers.
pub struct Format;

impl Format {
    /// Format a fraction as a percentage string, e.g. `percentage(0.25, 1)` -> `25.0%`.
    pub fn percentage(value: f64, precision: usize) -> String {
        format!("{:.prec$}%", value * 100.0, prec = precision)
    }

    /// Format a current/total pair, e.g. `progress(25, 100)` -> `25/100`.
    pub fn progress(current: u64, total: u64) -> String {
        format!("{}/{}", current, total)
    }
}

