mod indicators;

use indicators::{CyclicProgress, Format, ProgressDisplay};

fn main() {
    let mut cyclic1 = CyclicProgress::new(5);
    let mut cyclic2 = CyclicProgress::new(10);
    let mut cyclic3 = CyclicProgress::new(15);

    for _ in 0..3 {
        cyclic1.next();
    }
    for _ in 0..6 {
        cyclic2.next();
    }
    for _ in 0..9 {
        cyclic3.next();
    }

    println!("{}", cyclic1.str());
    println!("{}", cyclic2.str());
    println!("{}", cyclic3.str());

    let mut displays = [
        ProgressDisplay::new(50),
        ProgressDisplay::new(100),
        ProgressDisplay::new(200),
    ];

    displays[0].update(25);
    displays[1].update(75);
    displays[2].update(150);

    for d in displays.iter() {
        println!("{}", d.display());
    }

    displays[0].increment(5);
    displays[1].increment(10);
    displays[2].increment(20);

    for d in displays.iter() {
        println!("{}", d.display());
    }

    println!("{}", Format::percentage(0.25, 1));
    println!("{}", Format::percentage(0.5, 2));
    println!("{}", Format::percentage(0.75, 3));
    println!("{}", Format::progress(25, 100));
    println!("{}", Format::progress(50, 100));
    println!("{}", Format::progress(75, 100));
}

